-- Original PostgreSQL120 schedule/cron authority. The lineage's invented mandatory next_fire_at is now optional.
-- Keep every valid populated row and its previous compatibility cursor; native source writes omit that cursor.
-- This compatibility field and index grant no scheduling authority and are not used by the original cron executor.
-- Invalid legacy data is refused, never repaired or discarded. Static candidate parents are supplied by0334/0336.
INSERT INTO guard_fail(code) SELECT 'precondition_changed' WHERE EXISTS(SELECT 1 FROM environment_function_schedules legacy WHERE NOT((json_type(legacy.crons)='array' AND json_array_length(legacy.crons) BETWEEN 1 AND 8 AND NOT EXISTS(SELECT 1 FROM json_each(legacy.crons) item WHERE item.type<>'text' OR json_array_length('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']')<>5 OR NOT (((CAST(CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]') AS INTEGER) AS TEXT)=json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]') AND CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]') AS INTEGER) BETWEEN 0 AND 59) OR (substr(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]'),1,2)='*/' AND (CAST(CAST(substr(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]'),3) AS INTEGER) AS TEXT)=substr(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]'),3) AND CAST(substr(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[0]'),3) AS INTEGER) BETWEEN 5 AND 59))) AND (json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[1]')='*' OR (CAST(CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[1]') AS INTEGER) AS TEXT)=json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[1]') AND CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[1]') AS INTEGER) BETWEEN 0 AND 23)) AND (json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[2]')='*' OR (CAST(CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[2]') AS INTEGER) AS TEXT)=json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[2]') AND CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[2]') AS INTEGER) BETWEEN 1 AND 31)) AND (json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[3]')='*' OR (CAST(CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[3]') AS INTEGER) AS TEXT)=json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[3]') AND CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[3]') AS INTEGER) BETWEEN 1 AND 12)) AND (json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[4]')='*' OR (CAST(CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[4]') AS INTEGER) AS TEXT)=json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[4]') AND CAST(json_extract('[' || char(34) || replace(item.value, ' ', char(34)||','||char(34)) || char(34) || ']', '$[4]') AS INTEGER) BETWEEN 0 AND 6))) OR EXISTS(SELECT 1 FROM json_each(legacy.crons) prior WHERE prior.key<item.key AND prior.value>=item.value))) AND json_type(legacy.egress_allowed_origins)='array' AND (substr(legacy.immutable_script_name,1,2)='p-' AND substr(legacy.immutable_script_name,3,26) NOT GLOB '*[^a-z0-9]*' AND ((length(legacy.immutable_script_name)=59 AND substr(legacy.immutable_script_name,29,5)='-dev-' AND substr(legacy.immutable_script_name,34) NOT GLOB '*[^a-z0-9]*') OR (length(legacy.immutable_script_name)=60 AND substr(legacy.immutable_script_name,29,6)='-prod-' AND substr(legacy.immutable_script_name,35) NOT GLOB '*[^a-z0-9]*')))));
INSERT INTO guard_fail(code) SELECT 'precondition_changed' WHERE EXISTS(SELECT 1 FROM function_runs legacy WHERE NOT((length(legacy.organization_id)=26 AND substr(legacy.organization_id,1,1) BETWEEN '0' AND '7' AND legacy.organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*') AND (length(legacy.run_id)=26 AND substr(legacy.run_id,1,1) BETWEEN '0' AND '7' AND legacy.run_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*') AND (length(legacy.project_id)=26 AND substr(legacy.project_id,1,1) BETWEEN '0' AND '7' AND legacy.project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*') AND (length(legacy.environment_id)=26 AND substr(legacy.environment_id,1,1) BETWEEN '0' AND '7' AND legacy.environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*') AND (length(legacy.deployment_id)=26 AND substr(legacy.deployment_id,1,1) BETWEEN '0' AND '7' AND legacy.deployment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*') AND legacy.attempt BETWEEN 0 AND 3 AND json_type(legacy.egress_allowed_origins)='array' AND ((legacy.state='running')=(legacy.lease_until IS NOT NULL)) AND ((legacy.state IN ('succeeded','failed'))=(legacy.finished_at IS NOT NULL))));
CREATE TABLE environment_function_schedules_0361 (
  organization_id TEXT NOT NULL CHECK((length(organization_id)=26 AND substr(organization_id,1,1) BETWEEN '0' AND '7' AND organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*')), project_id TEXT NOT NULL CHECK((length(project_id)=26 AND substr(project_id,1,1) BETWEEN '0' AND '7' AND project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*')), environment_id TEXT NOT NULL CHECK((length(environment_id)=26 AND substr(environment_id,1,1) BETWEEN '0' AND '7' AND environment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*')),
  deployment_id TEXT NOT NULL CHECK((length(deployment_id)=26 AND substr(deployment_id,1,1) BETWEEN '0' AND '7' AND deployment_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*')), candidate_receipt_id TEXT NOT NULL CHECK((length(candidate_receipt_id)=26 AND substr(candidate_receipt_id,1,1) BETWEEN '0' AND '7' AND candidate_receipt_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*')), immutable_script_name TEXT NOT NULL,
  crons TEXT NOT NULL CHECK(json_valid(crons) AND json_type(crons)='array'),
  egress_allowed_origins TEXT NOT NULL CHECK(json_valid(egress_allowed_origins) AND json_type(egress_allowed_origins)='array'),
  next_fire_at TEXT CHECK(next_fire_at IS NULL OR next_fire_at GLOB '????-??-??T??:??:??.??????Z'),
  updated_at TEXT NOT NULL CHECK(updated_at GLOB '????-??-??T??:??:??.??????Z'),
  PRIMARY KEY(organization_id,environment_id),
  FOREIGN KEY(organization_id,project_id,environment_id) REFERENCES environments(organization_id,project_id,environment_id) ON DELETE CASCADE,
  FOREIGN KEY(organization_id,project_id,candidate_receipt_id) REFERENCES wfp_candidate_receipts(organization_id,project_id,candidate_receipt_id) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;
INSERT INTO environment_function_schedules_0361(organization_id,project_id,environment_id,deployment_id,candidate_receipt_id,immutable_script_name,crons,egress_allowed_origins,next_fire_at,updated_at)
 SELECT organization_id,project_id,environment_id,deployment_id,candidate_receipt_id,immutable_script_name,crons,egress_allowed_origins,next_fire_at,updated_at FROM environment_function_schedules;
